WITH prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM device_readings), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessions_device_readings AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, device_code, reading_ts, humidity, status_bits, firmware, session_start_flag, burst_id, CASE WHEN device_code RLIKE '^(DV-02|DV-03)$' THEN 'GROUP_B' WHEN device_code RLIKE '^(DV-01|DV-04)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS device_code_zone FROM sessions_device_readings ORDER BY firmware NULLS LAST, id
